#!/usr/bin/env python3
"""Variant and hook catalogs of the port's own code patchers (frame rate, display, guest guards, scene size), generated by running them.

    tools/recomp/variants/gen_patchers.py [--eboot out/eboot.elf] [--boot out/boot-linked.bin]   # writes patchers.txt and hooks-patchers.txt here
    tools/recomp/variants/gen_patchers.py --check

gen_patchers.cpp builds the real patcher sources (gpu/shim/bbport_frame_rate.cpp, bbport_display.cpp, bbport_guest_guards.cpp) with BB_HOOK_SITE_DUMP and
runs them against the game's flat image in the settings that install each of them (the default frame rate, a render size with the scene patch, a wide and
a tall output aspect). Every native hook site they declare goes into hooks-patchers.txt; the bytes the frame-rate patcher writes with hook slots (the
operand redirects to its `live` struct at the fixed place in the image, the nops, the run speed's divss) go into patchers.txt as group patcher:framerate,
an alternative to the community fps patch (excl=fps).
"""
import argparse
import os
import re
import struct
import subprocess
import sys
import tempfile
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
DATA_START = 0x56d3f00  # the unused end of the data segment (the cheats' flags, the frame rate's `live`): written by the patchers, not code


def flat_image(boot):
    f = boot.read_bytes()
    pos = 8
    size, entry, ns, nr, ni, caps, procparam, t0, t1, t2, t3, mc = struct.unpack_from('<12Q', f, pos)
    pos += 96 + mc * 7 * 8
    nb, = struct.unpack_from('<Q', f, pos)
    pos += 8 + nb * 24 + ns * 24 + ni * 128 + nr * 32
    img = f[pos:]
    assert len(img) == size
    return img


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument('--eboot', type=Path, default=ROOT / 'out/eboot.elf')
    ap.add_argument('--boot', type=Path, default=ROOT / 'out/boot-linked.bin')
    ap.add_argument('--check', action='store_true')
    args = ap.parse_args()
    with tempfile.TemporaryDirectory() as tmp:
        tmp = Path(tmp)
        subprocess.run([sys.executable, str(ROOT / 'tools/android/build_patch_parts.py'), '--out', str(tmp / 'parts'), '--eboot', str(args.eboot)],
                       check=True, stdout=subprocess.DEVNULL)
        (tmp / 'image.bin').write_bytes(flat_image(args.boot))
        exe = tmp / 'gen'
        subprocess.run(['c++', '-std=c++20', '-O1', '-w', '-DBB_HOOK_SITE_DUMP', '-I', str(ROOT / 'gpu/shim'), '-I', str(ROOT / 'gpu/shadps4'), '-I', str(ROOT / 'src'),
                        str(HERE / 'gen_patchers.cpp'), str(ROOT / 'gpu/shim/bbport_frame_rate.cpp'), str(ROOT / 'gpu/shim/bbport_display.cpp'),
                        str(ROOT / 'gpu/shim/bbport_guest_guards.cpp'), '-o', str(exe)], check=True)
        scenarios = [
            ({}, True),                                                       # the default frame rate, guards
            ({'BB_RENDER_RES': '1280x720'}, False),                           # a render size (with the scene patch)
            ({'BB_OUTPUT_RES': '2560x1080'}, False),                          # 21:9
            ({'BB_OUTPUT_RES': '1440x1080'}, False),                          # 4:3
        ]
        hooks = {}
        writes = []
        for env, take_bytes in scenarios:
            e = {k: v for k, v in os.environ.items() if not k.startswith('BB_')}
            e.update(env)
            parts = [str(tmp / 'parts' / 'res-scene.bin')] if 'BB_RENDER_RES' in env else []
            out = subprocess.run([str(exe), str(tmp / 'image.bin')] + parts, env=e, capture_output=True, text=True, check=True).stdout
            grp = False
            for line in out.split('\n'):
                m = re.match(r'^hook ([0-9a-f]+) (\d+) snap(?: resume=([0-9a-f,]+))?$', line)
                if m:
                    v = int(m.group(1), 16)
                    n = int(m.group(2))
                    r = {int(x, 16) for x in (m.group(3) or '').split(',') if x}
                    old = hooks.get(v, (0, set()))
                    hooks[v] = (max(n, old[0]), old[1] | r)
                elif line == '@group':
                    grp = True
                elif grp and take_bytes and line.startswith('@w '):
                    _, a, b = line.split()
                    if int(a, 16) < DATA_START:
                        writes.append((int(a, 16), b))
    head = '# Generated by tools/recomp/variants/gen_patchers.py: do not edit.'
    patches = '\n'.join([head, '# What the port\'s frame rate patcher writes into code when its detours are native hook slots (gpu/shim/bbport_frame_rate.cpp, InstallAllSlots).',
                         '', 'group patcher:framerate excl=fps'] + [f'w {a:x} {b}' for a, b in writes]) + '\n'
    lines = [head, '# Native hook sites of the port\'s patchers (bbport_frame_rate, bbport_display, bbport_guest_guards): the callbacks run where the stubs ran.']
    for v in sorted(hooks):
        n, r = hooks[v]
        lines.append(f'hook {v:x} {n} snap' + (' resume=' + ','.join(f'{x:x}' for x in sorted(r)) if r else ''))
    hooktext = '\n'.join(lines) + '\n'
    for name, text in (('patchers.txt', patches), ('hooks-patchers.txt', hooktext)):
        path = HERE / name
        if args.check:
            if not path.exists() or path.read_text() != text:
                print(f'{path} is out of date: rerun tools/recomp/variants/gen_patchers.py', file=sys.stderr)
                sys.exit(1)
        else:
            path.write_text(text)
            print(f'{path}: {len(text.splitlines())} lines')


if __name__ == '__main__':
    main()
